const email = String($json.email || '')
  .trim()
  .toLowerCase();

return {
  json: {
    ...$json,
    normalizedEmail: email,
    submitted_at: new Date().toISOString()
  }
};

const original = $('Prepare Lead Data').first().json;

const incomingEmail = String(original.normalizedEmail || '')
  .trim()
  .toLowerCase();

const incomingTime = new Date(original.submitted_at).getTime();

const twelveHours = 12 * 60 * 60 * 1000;

const rows = $input.all();

const duplicate = rows.some(item => {
  const sheetEmail = String(item.json.email || '')
    .trim()
    .toLowerCase();

  // Different email = not a duplicate
  if (sheetEmail !== incomingEmail) {
    return false;
  }

  const submittedAt = item.json.submitted_at;

  // No timestamp = ignore this old row
  if (!submittedAt) {
    return false;
  }

  const rowTime = new Date(submittedAt).getTime();

  // Invalid timestamp = ignore
  if (Number.isNaN(rowTime) || Number.isNaN(incomingTime)) {
    return false;
  }

  // Compare this request with the existing request
  const timeDifference = Math.abs(incomingTime - rowTime);

  return timeDifference <= twelveHours;
});

return [
  {
    json: {
      ...original,
      duplicate
    }
  }
];

const lead = $json.body;
const message = (lead.message || "").toLowerCase();
const budget = Number(lead.budget || 0);

// Explicit cold signals ALWAYS override everything else
const coldSignals = [
  "just looking",
  "just looking around",
  "just looking around for now",
  "just exploring",
  "only exploring",
  "browsing",
  "just checking",
  "just curious",
  "not ready",
  "not looking to buy"
];

if (coldSignals.some(signal => message.includes(signal))) {
  return {
    json: {
      ...$json,
      forced_classification: true,
      lead_type: "cold",
      reason: "Only browsing with no clear buying intent",
      priority: "low",
      service: "AI consulting"
    }
  };
}

// Strong hot signals
const hotSignals = [
  "start immediately",
  "ready to start",
  "ready to move forward",
  "approved budget",
  "budget has been approved",
  "allocated budget",
  "need this implemented",
  "need it implemented",
  "this month"
];

const hasHotSignal = hotSignals.some(signal => message.includes(signal));

if (hasHotSignal && budget > 0) {
  return {
    json: {
      ...$json,
      forced_classification: true,
      lead_type: "hot",
      reason: "Specific need, budget, and strong readiness to proceed",
      priority: "high",
      service: "AI implementation"
    }
  };
}

// Otherwise let the AI classify ambiguous leads
return {
  json: {
    ...$json,
    forced_classification: false
  }
};

const result = $json.output?.[0]?.content?.[0]?.text;

if (!result || typeof result !== "object") {
  throw new Error("AI returned no valid classification object");
}

const validLeadTypes = ["hot", "warm", "cold"];

if (!validLeadTypes.includes(result.lead_type)) {
  throw new Error(
    `Invalid lead_type returned by AI: "${result.lead_type}". Expected hot, warm, or cold.`
  );
}

if (!result.service) {
  throw new Error("AI classification is missing service");
}

// Priority is derived from lead_type.
// We do not need the AI to decide this separately.
const priorityMap = {
  hot: "high",
  warm: "normal",
  cold: "low"
};

return {
  json: {
    ...$json,
    lead_type: result.lead_type,
    service: result.service,
    urgency: result.urgency || "unknown",
    reason: result.summary || "No summary provided",
    priority: priorityMap[result.lead_type]
  }
};

const response = `Hi ${$json.name},

Thanks for reaching out about ${$json.service}. We’ve received your inquiry and will get back to you shortly.

Best regards,
${$('Client Config').item.json.business_name}`;

return {
  json: {
    ...$json,
    response: response
  }
};

