const requiredFields = [
  "name",
  "email",
  "company",
  "message",
  "budget"
];

const missingFields = requiredFields.filter(field => {
  const value = $json[field];
  return value === undefined || value === null || String(value).trim() === "";
});

return {
  json: {
    ...$json,
    valid: missingFields.length === 0,
    missingFields
  }
};
